svg.script:


var mirrored = false;

	/* onLoad will get image of hand, mirror the image if needed and start animation 
	*/
	function onLoad() {
		// mirror svg image if used as left hand
		mirrored = window.parent.getMirrored();
		if (mirrored) {
			var gui = document.getElementById('MirroredEndPosition');
			gui.setAttribute("transform","scale(-1, 1) translate(-800,0)");
		}


		// Get URI argument from html
		var args = window.parent.getArguments();

		// Diplay Result icon. Limit to the icon # 0 to 8 and 11 in graphic array.
		if (args.Result >= 0 && args.Result <= 11) {	
			SetResult(args.Result);
		}

		// Enable buttons
		SetButton(args.ButtonRetry, "Retry");
		SetButton(args.ButtonConfirm, "Confirm");

		Animate();
	}


	/********************************************************************************
		Called by onLoad
		SetResult will show or hide the Result Icons by Result-Parameter
	Input:
	  result icon number
		1 - green Icon (OK) displayed when capture is complete
		2 - General error
		3 - Clean Platen
		4 - Recording error
		5 - Roll error
		6 - Segmentation error displayed if flat captured images can not be segmented
		7 - Quality-Check error
		8 - Sequence-Check error displayed when fingerprint does not match flat capture
	********************************************************************************/
	function SetResult(result) {
		var i;

		// loop to hide all of the Result Icons and show only the correct one
		for (i = 1; i <= 11; i++) {
			// All the Result icon images are in the format IDIconResult_X where X is the Argument number 
			var resultIcon = document.getElementById('IDIconResult_' + i);
			if (resultIcon) {
				if (i == result) {
					resultIcon.setAttribute("display","inline");	// Display icon
				}
				else
					resultIcon.setAttribute("display","none");		// hide icon
			}
		}
	}

	/********************************************************************************
	  called by onLoad
	  SetButton will change the button icon to the active or inactive state
	  The button names are:
		IDButtonRetryActive
		IDButtonRetryInactive
		IDButtonConfirmActive
		IDButtonConfirmInactive
	INPUTS:
		state 	0 - inactive button is grayed out
				1 - active button is raised
				2 - button is hidden
		button  - string containing the name of the button. Used to get graphics element
				 must be set to "Retry" or "Confirm".
	********************************************************************************/
	function SetButton(state, button) {
		var ActiveButtonIcon = document.getElementById('IDButton' + button + 'Active');
		var InactiveButtonIcon = document.getElementById('IDButton' + button + 'Inactive');

		switch(state) {
			case 0:
				//inactive
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","inline");
				if (button == "Confirm") {
					MoveRetryButton(0);
				}
				break;

			case 1:
				//active
				ActiveButtonIcon.setAttribute("display","inline");
				InactiveButtonIcon.setAttribute("display","none");
				if (button == "Confirm") {
					MoveRetryButton(0);
				}
				break;

			case 2:
				//hidden
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","none");

				//if the Button "Confirm" is not visible, move the Retry-Button to right
				if (button == "Confirm") {
					MoveRetryButton(1);
				}
				break;

			default:
				//inactive
				ActiveButtonIcon.setAttribute("display","none");
				InactiveButtonIcon.setAttribute("display","inline");
				break;
		}
	}


	/********************************************************************************
	  called by SetButton
	  MoveRetryButton will preposition Retry button if Confirm button is hidden

	INPUTL
		position - Retry button position
				   0 - initial possition as defined by SVG graphics
				   1 - move button to left
	********************************************************************************/
	function MoveRetryButton(position) {
		var retryBtn1 = document.getElementById('IDButtonRetryActive');
		var retryBtn2 = document.getElementById('IDButtonRetryInactive');

		if (position == 1) {
			retryBtn1.setAttribute("transform","translate(113,0)");
			retryBtn2.setAttribute("transform","translate(113,0)");
		} 
		else {
			retryBtn1.setAttribute("transform","translate(0,0)");	// original position
			retryBtn2.setAttribute("transform","translate(0,0)");			
		}
	}


	/********************************************************************************
	 Animate will get image of hand, calculate new position and display image
	********************************************************************************/
	function Animate() {
		var regularHand = document.getElementById('EndPosition');
		regularHand.setAttribute("display","none");		// hide hand

		var endX = 400;
		var endY = -420;
		var percentageMoved = 0;

		window.clearInterval(window.timer);

		window.timer = window.setInterval(
			function() {
				percentageMoved += 0.05;
				scaleRate2 = 2 - percentageMoved;
				if (percentageMoved > 1.05) {
					window.clearInterval(window.timer); 
					setTimeout(
						function(){
							Animate();
						}
						,1200); 	// 1200 millisecond delay after each animation cycle
					return; 
				}
				else {
					var x2 = endX * (1 - percentageMoved);
					var y2 = endY * (1- percentageMoved);

					// Build the text versions of the translate and scale transformation
					var trans2 = "translate(" + x2 + ", " + y2 + ")";
					var scale2 = "scale(" + scaleRate2 + ", " + scaleRate2 + ")";

					// Apply the transformation 
					regularHand.setAttributeNS(null, "transform", trans2 + " " + scale2);
					regularHand.setAttribute("display","inline");	// display image
				}				
			} 
			,100);  // 100 millisecond delay after each animation frame
	}
